        CREATE INDEX idx_ledgers_fast_sync ON ledgers (accountId, timestamp DESC);
        CREATE INDEX idx_users_dealer ON users (dealerId);
    `);

    console.log("Database initialized with scale-ready indices.");
    db.close();
}
