const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');

const DB_PATH = path.join(__dirname, 'database.sqlite');
const SEED_FILE = path.join(__dirname, 'db.json');

function main() {
    console.log("==================================================");
    console.log("   A-BABA EXCHANGE: SQL RECONSTRUCTION TOOL   ");
    console.log("==================================================");

    // 1. Force a complete wipe
    if (fs.existsSync(DB_PATH)) {
        console.log("[1/4] Existing database found. Wiping...");
        try {
            // Attempt to change permissions just in case it's read-only
            fs.chmodSync(DB_PATH, 0o666);
            fs.unlinkSync(DB_PATH);
            console.log("      SUCCESS: Old database deleted.");
        } catch (err) {
            console.error("      FATAL ERROR: Could not delete database.sqlite.");
            console.error("      REASON: " + err.message);
            console.error("      FIX: Run 'pm2 stop ababa-backend' first.");
            process.exit(1);
        }
    } else {
        console.log("[1/4] No existing database found. Starting fresh.");
    }

    // 2. Open fresh connection
    let db;
    try {
        db = new Database(DB_PATH);
        db.pragma('journal_mode = WAL');
        console.log("[2/4] Created fresh SQLite container.");
    } catch (e) {
        console.error("      FATAL: Connection failed.");
        console.error(e.message);
        process.exit(1);
    }

    // 3. Re-create Tables
    console.log("[3/4] Building Schema...");
    try {
        db.exec(`
            CREATE TABLE admins (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                password TEXT NOT NULL, 
                wallet REAL DEFAULT 0, 
                prizeRates TEXT, 
                avatarUrl TEXT
            );

            CREATE TABLE dealers (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                password TEXT NOT NULL, 
                area TEXT, 
                contact TEXT, 
                wallet REAL DEFAULT 0, 
                commissionRate REAL DEFAULT 0, 
                isRestricted INTEGER DEFAULT 0, 
                prizeRates TEXT, 
                avatarUrl TEXT
            );

            CREATE TABLE users (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                password TEXT NOT NULL, 
                dealerId TEXT NOT NULL, 
                area TEXT, 
                contact TEXT, 
                wallet REAL DEFAULT 0, 
                commissionRate REAL DEFAULT 0, 
                isRestricted INTEGER DEFAULT 0, 
                prizeRates TEXT, 
                betLimits TEXT, 
                avatarUrl TEXT,
                FOREIGN KEY (dealerId) REFERENCES dealers(id)
            );

            CREATE TABLE games (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                drawTime TEXT NOT NULL, 
                winningNumber TEXT, 
                payoutsApproved INTEGER DEFAULT 0
            );

            CREATE TABLE bets (
                id TEXT PRIMARY KEY, 
                userId TEXT NOT NULL, 
                dealerId TEXT NOT NULL, 
                gameId TEXT NOT NULL, 
                subGameType TEXT NOT NULL, 
                numbers TEXT NOT NULL, 
                amountPerNumber REAL NOT NULL, 
                totalAmount REAL NOT NULL, 
                timestamp TEXT NOT NULL,
                FOREIGN KEY (userId) REFERENCES users(id),
                FOREIGN KEY (dealerId) REFERENCES dealers(id),
                FOREIGN KEY (gameId) REFERENCES games(id)
            );

            CREATE TABLE ledgers (
                id TEXT PRIMARY KEY, 
                accountId TEXT NOT NULL, 
                accountType TEXT NOT NULL, 
                timestamp TEXT NOT NULL, 
                description TEXT NOT NULL, 
                debit REAL DEFAULT 0, 
                credit REAL DEFAULT 0, 
                balance REAL DEFAULT 0
            );

            CREATE TABLE number_limits (
                id INTEGER PRIMARY KEY AUTOINCREMENT, 
                gameType TEXT NOT NULL, 
                numberValue TEXT NOT NULL, 
                limitAmount REAL NOT NULL, 
                UNIQUE(gameType, numberValue)
            );
        `);
        console.log("      SUCCESS: Tables built.");
    } catch (e) {
        console.error("      ERROR: Schema construction failed.");
        console.error(e.message);
        process.exit(1);
    }

    // 4. Seed Data
    if (fs.existsSync(SEED_FILE)) {
        console.log("[4/4] Importing Seed Data (Guru, Games, Dealers)...");
        try {
            const data = JSON.parse(fs.readFileSync(SEED_FILE, 'utf8'));

            db.transaction(() => {
                const insAdmin = db.prepare('INSERT INTO admins (id, name, password, wallet, prizeRates, avatarUrl) VALUES (?, ?, ?, ?, ?, ?)');
                insAdmin.run(data.admin.id, data.admin.name, data.admin.password, data.admin.wallet, JSON.stringify(data.admin.prizeRates), data.admin.avatarUrl);

                const insGame = db.prepare('INSERT INTO games (id, name, drawTime) VALUES (?, ?, ?)');
                data.games.forEach(g => insGame.run(g.id, g.name, g.drawTime));

                const insDealer = db.prepare('INSERT INTO dealers (id, name, password, area, contact, wallet, commissionRate, prizeRates, avatarUrl) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)');
                data.dealers.forEach(d => insDealer.run(d.id, d.name, d.password, d.area, d.contact, d.wallet, d.commissionRate, JSON.stringify(d.prizeRates), d.avatarUrl));

                const insUser = db.prepare('INSERT INTO users (id, name, password, dealerId, area, contact, wallet, commissionRate, prizeRates, avatarUrl) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');
                data.users.forEach(u => insUser.run(u.id, u.name, u.password, u.dealerId, u.area, u.contact, u.wallet, u.commissionRate, JSON.stringify(u.prizeRates), u.avatarUrl));

                const insLedger = db.prepare('INSERT INTO ledgers (id, accountId, accountType, timestamp, description, debit, credit, balance) VALUES (?, ?, ?, ?, ?, ?, ?, ?)');
                if (data.admin.ledger) {
                    data.admin.ledger.forEach(l => {
                        insLedger.run(l.id, data.admin.id, 'ADMIN', l.timestamp, l.description, l.debit, l.credit, l.balance);
                    });
                }
            })();
            console.log("      SUCCESS: Data imported.");
        } catch (e) {
            console.error("      ERROR: Data import failed.");
            console.error(e.message);
            process.exit(1);
        }
    }

    db.close();
    console.log("==================================================");
    console.log("   RECONSTRUCTION SUCCESSFUL! RESTART PM2 NOW.   ");
    console.log("==================================================");
}

main();

require('dotenv').config();
const express = require('express');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const authMiddleware = require('./authMiddleware');
const database = require('./database');
const { GoogleGenAI } = require("@google/genai");

const app = express();
app.use(cors());
app.use(express.json());

// Initialize Gemini
const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Initialize Database connection
let dbReady = false;
let dbError = null;
let dbRawError = null;

const tryInitDB = () => {
    try {
        database.connect();
        if (database.verifySchema()) {
            dbReady = true;
            dbError = null;
            dbRawError = null;
            console.log("[SERVER] Database is ready.");
            return true;
        } else {
            dbError = "Schema incomplete. Please run setup-database.js.";
            console.error("[SERVER] " + dbError);
        }
    } catch (e) {
        dbError = e.message;
        dbRawError = e.raw || e.toString();
        console.error("[SERVER] FATAL: Database failed to start.");
    }
    return false;
};

// Initial attempt
tryInitDB();

// Global JSON response header and DB check middleware
app.use('/api', (req, res, next) => {
    res.setHeader('Content-Type', 'application/json');
    // If DB is not ready, try to re-init once more for health check requests
    if (!dbReady && (req.path === '/status' || req.path === '/games')) {
        tryInitDB();
    }
    next();
});

// Health Check
app.get('/api/status', (req, res) => {
    res.json({ 
        status: dbReady ? "online" : "error", 
        database: dbReady ? "connected" : "failed",
        error: dbError,
        raw: dbRawError
    });
});

// --- PUBLIC ---
app.get('/api/games', (req, res) => {
    if (!dbReady) {
        return res.status(503).json({ 
            error: dbError || "Database Offline", 
            details: "The SQL link is severed. This usually means the binary driver crashed or the database file is missing.",
            raw: dbRawError,
            fix: "Run: cd backend && pm2 stop ababa-backend && npm run db:setup && pm2 start server.js --name ababa-backend"
        });
    }
    try {
        const games = database.getAllFromTable('games');
        res.json(games);
    } catch (e) {
        res.status(500).json({ error: "Query failed", details: e.message });
    }
});

// --- AI LUCKY PICK ---
app.get('/api/user/ai-lucky-pick', authMiddleware, async (req, res) => {
    try {
        const type = req.query.type || '2-digit';
        const gameName = req.query.gameName || 'Ali Baba';

        const prompt = `You are a mystical numerologist for a lottery platform. 
        The user is playing a game called "${gameName}". 
        Generate ${type === '2-digit' ? 'three different 2-digit numbers (00-99)' : 'three different 1-digit numbers (0-9)'}.
        Provide the response in JSON format like: {"numbers": ["12", "45", "78"]} or {"numbers": ["4", "7", "2"]}.
        Make the choice feel special and based on the cosmos. Only return JSON.`;

        const response = await genAI.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });

        const result = JSON.parse(response.text);
        res.json(result);
    } catch (e) {
        console.error("[AI] Error:", e);
        res.status(500).json({ error: "AI failed to suggest numbers." });
    }
});

// --- AUTH ---
app.post('/api/auth/login', (req, res) => {
    const { loginId, password } = req.body;
    try {
        const { account, role } = database.findAccountForLogin(loginId);
        if (account && account.password === password) {
            const token = jwt.sign({ id: account.id, role }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
            const fullAccount = database.findAccountById(account.id, role.toLowerCase() + 's');
            return res.json({ token, role, account: fullAccount });
        }
        res.status(401).json({ message: "Invalid credentials" });
    } catch (e) {
        res.status(500).json({ message: "Internal login error", error: e.message });
    }
});

app.get('/api/auth/verify', authMiddleware, (req, res) => {
    try {
        const account = database.findAccountById(req.user.id, req.user.role.toLowerCase() + 's');
        if (!account) return res.status(404).json({ message: "Account not found." });
        res.json({ account, role: req.user.role });
    } catch (e) {
        res.status(500).json({ message: "Verification failed.", error: e.message });
    }
});

// --- DATA SYNC ---
app.get('/api/admin/data', authMiddleware, (req, res) => {
    if (req.user.role !== 'ADMIN') return res.sendStatus(403);
    try {
        res.json({
            dealers: database.getAllFromTable('dealers'),
            users: database.getAllFromTable('users'),
            games: database.getAllFromTable('games'),
            bets: database.getAllFromTable('bets')
        });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

