 */
function reinstall() {
    console.log("==================================================");
    console.log("   A-BABA EXCHANGE: SQL REINSTALLATION TOOL   ");
    console.log("==================================================");

    // 1. Force Delete Old Data
    if (fs.existsSync(DB_PATH)) {
        console.log("[1/4] Old database found. Wiping data...");
        try {
            fs.unlinkSync(DB_PATH);
            console.log("      SUCCESS: database.sqlite deleted.");
        } catch (err) {
            console.error("      ERROR: Could not delete database.sqlite.");
            console.error("      REASON: " + err.message);
            console.error("      FIX: Run 'pm2 stop ababa-backend' first.");
            process.exit(1);
        }
    } else {
        console.log("[1/4] No old database found. Clean start.");
    }

    // 2. Open fresh connection
    let db;
    try {
        db = new Database(DB_PATH);
        db.pragma('journal_mode = WAL');
        db.pragma('foreign_keys = ON');
        console.log("[2/4] Created fresh SQL container.");
    } catch (e) {
        console.error("      FATAL: Connection failed.");
        console.error(e.message);
        process.exit(1);
    }

    // 3. Re-create All Tables
    console.log("[3/4] Building Tables...");
    try {
        db.exec(`
            CREATE TABLE admins (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                password TEXT NOT NULL, 
                wallet REAL DEFAULT 0, 
                prizeRates TEXT, 
                avatarUrl TEXT
            );

            CREATE TABLE dealers (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                password TEXT NOT NULL, 
                area TEXT, 
                contact TEXT, 
                wallet REAL DEFAULT 0, 
                commissionRate REAL DEFAULT 0, 
                isRestricted INTEGER DEFAULT 0, 
                prizeRates TEXT, 
                avatarUrl TEXT
            );

            CREATE TABLE users (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                password TEXT NOT NULL, 
                dealerId TEXT NOT NULL, 
                area TEXT, 
                contact TEXT, 
                wallet REAL DEFAULT 0, 
                commissionRate REAL DEFAULT 0, 
                isRestricted INTEGER DEFAULT 0, 
                prizeRates TEXT, 
                betLimits TEXT, 
                avatarUrl TEXT,
                FOREIGN KEY (dealerId) REFERENCES dealers(id)
            );

            CREATE TABLE games (
                id TEXT PRIMARY KEY, 
                name TEXT NOT NULL, 
                drawTime TEXT NOT NULL, 
                winningNumber TEXT, 
                payoutsApproved INTEGER DEFAULT 0
            );

            CREATE TABLE bets (
                id TEXT PRIMARY KEY, 
                userId TEXT NOT NULL, 
                dealerId TEXT NOT NULL, 
                gameId TEXT NOT NULL, 
                subGameType TEXT NOT NULL, 
                numbers TEXT NOT NULL, 
                amountPerNumber REAL NOT NULL, 
                totalAmount REAL NOT NULL, 
                timestamp TEXT NOT NULL,
                FOREIGN KEY (userId) REFERENCES users(id),
                FOREIGN KEY (dealerId) REFERENCES dealers(id),
                FOREIGN KEY (gameId) REFERENCES games(id)
            );

            CREATE TABLE ledgers (
                id TEXT PRIMARY KEY, 
                accountId TEXT NOT NULL, 
                accountType TEXT NOT NULL, 
                timestamp TEXT NOT NULL, 
                description TEXT NOT NULL, 
                debit REAL DEFAULT 0, 
                credit REAL DEFAULT 0, 
                balance REAL DEFAULT 0
            );

            CREATE TABLE number_limits (
                id INTEGER PRIMARY KEY AUTOINCREMENT, 
                gameType TEXT NOT NULL, 
                numberValue TEXT NOT NULL, 
                limitAmount REAL NOT NULL, 
                UNIQUE(gameType, numberValue)
            );
        `);
        console.log("      SUCCESS: Tables created.");
    } catch (e) {
        console.error("      ERROR: Table creation failed.");
        console.error(e.message);
        process.exit(1);
    }

    // 4. Seed Guru and Initial Data
    if (fs.existsSync(SEED_FILE)) {
        console.log("[4/4] Importing initial Guru/Dealers/Games...");
        try {
            const data = JSON.parse(fs.readFileSync(SEED_FILE, 'utf8'));

            db.transaction(() => {
                const insAdmin = db.prepare('INSERT INTO admins (id, name, password, wallet, prizeRates, avatarUrl) VALUES (?, ?, ?, ?, ?, ?)');
                insAdmin.run(data.admin.id, data.admin.name, data.admin.password, data.admin.wallet, JSON.stringify(data.admin.prizeRates), data.admin.avatarUrl);

                const insGame = db.prepare('INSERT INTO games (id, name, drawTime) VALUES (?, ?, ?)');
                data.games.forEach(g => insGame.run(g.id, g.name, g.drawTime));

                const insDealer = db.prepare('INSERT INTO dealers (id, name, password, area, contact, wallet, commissionRate, prizeRates, avatarUrl) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)');
                data.dealers.forEach(d => insDealer.run(d.id, d.name, d.password, d.area, d.contact, d.wallet, d.commissionRate, JSON.stringify(d.prizeRates), d.avatarUrl));

                const insUser = db.prepare('INSERT INTO users (id, name, password, dealerId, area, contact, wallet, commissionRate, prizeRates, avatarUrl) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');
                data.users.forEach(u => insUser.run(u.id, u.name, u.password, u.dealerId, u.area, u.contact, u.wallet, u.commissionRate, JSON.stringify(u.prizeRates), u.avatarUrl));

                const insLedger = db.prepare('INSERT INTO ledgers (id, accountId, accountType, timestamp, description, debit, credit, balance) VALUES (?, ?, ?, ?, ?, ?, ?, ?)');
                if (data.admin.ledger) {
                    data.admin.ledger.forEach(l => {
                        insLedger.run(l.id, data.admin.id, 'ADMIN', l.timestamp, l.description, l.debit, l.credit, l.balance);
                    });
                }
            })();
            console.log("      SUCCESS: Initial data imported.");
        } catch (e) {
            console.error("      ERROR: Data import failed.");
            console.error(e.message);
            process.exit(1);
        }
    }

    db.close();
    console.log("==================================================");
    console.log("   REINSTALLATION SUCCESSFUL! RESTART PM2.   ");
    console.log("==================================================");
}

reinstall();

const path = require('path');
const Database = require('better-sqlite3');
const fs = require('fs');

const DB_PATH = path.join(__dirname, 'database.sqlite');
let _db = null;

const connect = () => {
    if (_db) return _db;

    try {
        console.log(`[DB] Attempting to link: ${DB_PATH}`);

        // Ensure folder exists
        const dir = path.dirname(DB_PATH);
        if (!fs.existsSync(dir)) {
            fs.mkdirSync(dir, { recursive: true });
        }

        _db = new Database(DB_PATH, { timeout: 10000 });
        _db.pragma('journal_mode = WAL');
        _db.pragma('foreign_keys = ON');

        // Connectivity test
        _db.prepare("SELECT 1").get();

        console.log('[DB] SQL Link Established.');
        return _db;
    } catch (e) {
        console.error("--- DATABASE LINK FAILURE ---");
        console.error(e.message);

        let msg = "Database Offline";
        let fix = "Run 'npm run db:setup' on the server.";

        if (e.code === 'ERR_DLOPEN_FAILED' || e.message.includes('NODE_MODULE_VERSION')) {
            msg = "Binary Mismatch: Reinstall SQL Driver";
            fix = "Run: rm -rf node_modules && npm install && pm2 restart ababa-backend";
        } else if (!fs.existsSync(DB_PATH)) {
            msg = "Database Missing: SQL File Not Found";
            fix = "Run: npm run db:setup";
        }

        const err = new Error(msg);
        err.raw = e.message;
        err.fix = fix;
        throw err;
    }
};

const getDB = () => {
    if (!_db) return connect();
    return _db;
};

const safeParse = (str) => {
    try { return str ? JSON.parse(str) : null; } 
    catch (e) { return null; }
};

const getAllFromTable = (table) => {
    const db = getDB();
    try {
        const items = db.prepare(`SELECT * FROM ${table}`).all();
        return items.map(item => {
            if (item.prizeRates) item.prizeRates = safeParse(item.prizeRates);
            if (item.betLimits) item.betLimits = safeParse(item.betLimits);
            if (item.numbers) item.numbers = safeParse(item.numbers);
            return item;
        });
    } catch (err) {
        console.error(`[DB] Query failed for ${table}:`, err.message);
        throw err;
    }
};

module.exports = {
    connect,
    verifySchema: () => {
        try {
            const db = getDB();
            // Check essential tables
            const required = ['admins', 'games', 'dealers'];
            for (const table of required) {
                const res = db.prepare(`SELECT name FROM sqlite_master WHERE type='table' AND name=?`).get(table);
                if (!res) return false;
            }
            return true;
        } catch (e) {
            return false;
        }
    },
    getAllFromTable,
    findAccountForLogin: (loginId) => {
        const db = getDB();
        const roles = [{ table: 'users', role: 'USER' }, { table: 'dealers', role: 'DEALER' }, { table: 'admins', role: 'ADMIN' }];
        for (const r of roles) {
            const acc = db.prepare(`SELECT * FROM ${r.table} WHERE id = ?`).get(loginId);
            if (acc) return { account: acc, role: r.role };
        }
        return { account: null, role: null };
    },
    findAccountById: (id, table) => {
        const db = getDB();
        const acc = db.prepare(`SELECT * FROM ${table} WHERE id = ?`).get(id);
        if (!acc) return null;
        acc.prizeRates = safeParse(acc.prizeRates);
        acc.ledger = db.prepare('SELECT * FROM ledgers WHERE accountId = ? ORDER BY timestamp DESC LIMIT 50').all(id);
        return acc;
    },
    saveDealer: (d) => {
        const db = getDB();
        return db.prepare('INSERT OR REPLACE INTO dealers (id, name, password, area, contact, wallet, commissionRate, prizeRates, avatarUrl) VALUES (?,?,?,?,?,?,?,?,?)')
                 .run(d.id, d.name, d.password, d.area, d.contact, d.wallet, d.commissionRate, JSON.stringify(d.prizeRates), d.avatarUrl);
    },
    saveUser: (u) => {
        const db = getDB();
        return db.prepare('INSERT OR REPLACE INTO users (id, name, password, dealerId, area, contact, wallet, commissionRate, prizeRates, avatarUrl) VALUES (?,?,?,?,?,?,?,?,?,?)')
                 .run(u.id, u.name, u.password, u.dealerId, u.area, u.contact, u.wallet, u.commissionRate, JSON.stringify(u.prizeRates), u.avatarUrl);
    },
    runInTransaction: (fn) => getDB().transaction(fn)()
};

