const path = require('path');
const sqlite3 = require('sqlite3').verbose();
const { v4: uuidv4 } = require('uuid');

const DB_PATH = path.join(__dirname, 'database.sqlite');
let db;

const PKT_OFFSET_HOURS = 5;
const OPEN_HOUR_PKT = 16; 

function getGameCycle(drawTime) {
    const now = new Date();
    const [drawHoursPKT, drawMinutesPKT] = drawTime.split(':').map(Number);
    const year = now.getUTCFullYear();
    const month = now.getUTCMonth();
    const day = now.getUTCDate();
    const openHourUTC = OPEN_HOUR_PKT - PKT_OFFSET_HOURS;

    const todayOpen = new Date(Date.UTC(year, month, day, openHourUTC, 0, 0));
    const yesterdayOpen = new Date(todayOpen.getTime() - (24 * 60 * 60 * 1000));

    const calculateCloseTime = (openDate) => {
        const closeDate = new Date(openDate.getTime());
        const drawHourUTC = drawHoursPKT - PKT_OFFSET_HOURS;
        closeDate.setUTCHours(drawHourUTC, drawMinutesPKT, 0, 0);
        if (drawHoursPKT < OPEN_HOUR_PKT) {
            closeDate.setUTCDate(closeDate.getUTCDate() + 1);
        }
        return closeDate;
    };

    const yesterdayCycleClose = calculateCloseTime(yesterdayOpen);
    if (now >= yesterdayOpen && now < yesterdayCycleClose) {
        return { openTime: yesterdayOpen, closeTime: yesterdayCycleClose };
    }
    const todayCycleClose = calculateCloseTime(todayOpen);
    return { openTime: todayOpen, closeTime: todayCycleClose };
}

function isGameOpen(drawTime) {
    const now = new Date();
    const { openTime, closeTime } = getGameCycle(drawTime);
    return now >= openTime && now < closeTime;
}

const connect = () => {
    db = new sqlite3.Database(DB_PATH, (err) => {
        if (err) {
            console.error('Failed to connect to database:', err);
            process.exit(1);
        }
        console.error('Database connected successfully (SQLite3).');
        db.run('PRAGMA journal_mode = WAL');
        db.run('PRAGMA foreign_keys = ON');
    });
};

const query = (sql, params = []) => {
    return new Promise((resolve, reject) => {
        db.all(sql, params, (err, rows) => {
            if (err) reject(err);
            else resolve(rows);
        });
    });
};

const get = (sql, params = []) => {
    return new Promise((resolve, reject) => {
        db.get(sql, params, (err, row) => {
            if (err) reject(err);
            else resolve(row);
        });
    });
};

const run = (sql, params = []) => {
    return new Promise((resolve, reject) => {
        db.run(sql, params, function(err) {
            if (err) reject(err);
            else resolve({ id: this.lastID, changes: this.changes });
        });
    });
};

const verifySchema = async () => {
    const row = await get("SELECT name FROM sqlite_master WHERE type='table' AND name='admins'");
    if (!row) {
        console.error('CRITICAL: Database schema missing. Run npm run db:setup.');
        process.exit(1);
    }
};

const findAccountById = async (id, table) => {
    const account = await get(`SELECT * FROM ${table} WHERE id = ?`, [id]);
    if (!account) return null;

    if (table !== 'games') {
        const ledgers = await query('SELECT * FROM ledgers WHERE accountId = ? ORDER BY timestamp ASC', [id]);
        account.ledger = ledgers;
    } else {
        account.isMarketOpen = isGameOpen(account.drawTime);
    }

    if (account.prizeRates) account.prizeRates = JSON.parse(account.prizeRates);
    if (account.betLimits) account.betLimits = JSON.parse(account.betLimits);
    if (account.isRestricted !== undefined) account.isRestricted = !!account.isRestricted;

    return account;
};

const findAccountForLogin = async (loginId) => {
    const tables = [{ name: 'users', role: 'USER' }, { name: 'dealers', role: 'DEALER' }, { name: 'admins', role: 'ADMIN' }];
    for (const tableInfo of tables) {
        const account = await get(`SELECT * FROM ${tableInfo.name} WHERE lower(id) = ?`, [loginId.toLowerCase()]);
        if (account) return { account, role: tableInfo.role };
    }
    return { account: null, role: null };
};

const getAllFromTable = async (table, withLedger = false) => {
    const rows = await query(`SELECT * FROM ${table}`);
    return Promise.all(rows.map(async (acc) => {
        if (withLedger) acc.ledger = await query('SELECT * FROM ledgers WHERE accountId = ? ORDER BY timestamp ASC', [acc.id]);
        if (table === 'games') acc.isMarketOpen = isGameOpen(acc.drawTime);
        if (acc.prizeRates) acc.prizeRates = JSON.parse(acc.prizeRates);
        if (acc.betLimits) acc.betLimits = JSON.parse(acc.betLimits);
        if (acc.numbers) acc.numbers = JSON.parse(acc.numbers);
        if (acc.isRestricted !== undefined) acc.isRestricted = !!acc.isRestricted;
        return acc;
    }));
};

const addLedgerEntry = async (accountId, accountType, description, debit, credit) => {
    const table = accountType.toLowerCase() + 's';
    const lastEntry = await get('SELECT balance FROM ledgers WHERE accountId = ? ORDER BY timestamp DESC, ROWID DESC LIMIT 1', [accountId]);
    const lastBalance = lastEntry ? lastEntry.balance : 0;

    if (debit > 0 && accountType !== 'ADMIN' && lastBalance < debit) {
        throw { status: 400, message: `Insufficient funds.` };
    }

    const newBalance = lastBalance - debit + credit;
    await run('INSERT INTO ledgers (id, accountId, accountType, timestamp, description, debit, credit, balance) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
        [uuidv4(), accountId, accountType, new Date().toISOString(), description, debit, credit, newBalance]);
    await run(`UPDATE ${table} SET wallet = ? WHERE id = ?`, [newBalance, accountId]);
};

module.exports = {
    connect, verifySchema, findAccountById, findAccountForLogin, getAllFromTable, addLedgerEntry, get, run, query,
    runInTransaction: (fn) => db.serialize(fn),
    updatePassword: async (id, contact, pass) => {
        for (const t of ['users', 'dealers']) {
            const res = await run(`UPDATE ${t} SET password = ? WHERE id = ? AND contact = ?`, [pass, id, contact]);
            if (res.changes > 0) return true;
        }
        return false;
    }
};

const fs = require('fs');
const path = require('path');
const sqlite3 = require('sqlite3').verbose();
const { v4: uuidv4 } = require('uuid');

const DB_PATH = path.join(__dirname, 'database.sqlite');
const JSON_DB_PATH = path.join(__dirname, 'db.json');

async function main() {
    if (fs.existsSync(DB_PATH)) fs.unlinkSync(DB_PATH);
    const db = new sqlite3.Database(DB_PATH);

    const schema = `
        CREATE TABLE admins (id TEXT PRIMARY KEY, name TEXT NOT NULL, password TEXT NOT NULL, wallet REAL NOT NULL, prizeRates TEXT NOT NULL, avatarUrl TEXT);
        CREATE TABLE dealers (id TEXT PRIMARY KEY, name TEXT NOT NULL, password TEXT NOT NULL, area TEXT, contact TEXT, wallet REAL NOT NULL, commissionRate REAL NOT NULL, isRestricted INTEGER NOT NULL DEFAULT 0, prizeRates TEXT NOT NULL, avatarUrl TEXT);
        CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, password TEXT NOT NULL, dealerId TEXT NOT NULL, area TEXT, contact TEXT, wallet REAL NOT NULL, commissionRate REAL NOT NULL, isRestricted INTEGER NOT NULL DEFAULT 0, prizeRates TEXT NOT NULL, betLimits TEXT, avatarUrl TEXT, FOREIGN KEY (dealerId) REFERENCES dealers(id));
        CREATE TABLE games (id TEXT PRIMARY KEY, name TEXT NOT NULL, drawTime TEXT NOT NULL, winningNumber TEXT, payoutsApproved INTEGER DEFAULT 0);
        CREATE TABLE bets (id TEXT PRIMARY KEY, userId TEXT NOT NULL, dealerId TEXT NOT NULL, gameId TEXT NOT NULL, subGameType TEXT NOT NULL, numbers TEXT NOT NULL, amountPerNumber REAL NOT NULL, totalAmount REAL NOT NULL, timestamp TEXT NOT NULL, FOREIGN KEY (userId) REFERENCES users(id), FOREIGN KEY (dealerId) REFERENCES dealers(id), FOREIGN KEY (gameId) REFERENCES games(id));
        CREATE TABLE ledgers (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, accountType TEXT NOT NULL, timestamp TEXT NOT NULL, description TEXT NOT NULL, debit REAL NOT NULL, credit REAL NOT NULL, balance REAL NOT NULL);
        CREATE TABLE number_limits (id INTEGER PRIMARY KEY AUTOINCREMENT, gameType TEXT NOT NULL, numberValue TEXT NOT NULL, limitAmount REAL NOT NULL, UNIQUE(gameType, numberValue));
    `;

    db.serialize(() => {
        schema.split(';').filter(s => s.trim()).forEach(s => db.run(s));

        if (fs.existsSync(JSON_DB_PATH)) {
            const data = JSON.parse(fs.readFileSync(JSON_DB_PATH, 'utf-8'));
            const admin = data.admin;
            db.run('INSERT INTO admins VALUES (?,?,?,?,?,?)', [admin.id, admin.name, admin.password, admin.wallet, JSON.stringify(admin.prizeRates), admin.avatarUrl]);
            data.dealers.forEach(d => db.run('INSERT INTO dealers VALUES (?,?,?,?,?,?,?,?,?,?)', [d.id, d.name, d.password, d.area, d.contact, d.wallet, d.commissionRate, 0, JSON.stringify(d.prizeRates), d.avatarUrl]));
            data.users.forEach(u => db.run('INSERT INTO users VALUES (?,?,?,?,?,?,?,?,?,?,?,?)', [u.id, u.name, u.password, u.dealerId, u.area, u.contact, u.wallet, u.commissionRate, 0, JSON.stringify(u.prizeRates), JSON.stringify(u.betLimits), u.avatarUrl]));
            data.games.forEach(g => db.run('INSERT INTO games VALUES (?,?,?,?,?)', [g.id, g.name, g.drawTime, g.winningNumber || null, g.payoutsApproved ? 1 : 0]));
        }
    });

    console.log('Database initialized successfully.');
}
main();

require('dotenv').config();
const express = require('express');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const authMiddleware = require('./authMiddleware');
const { GoogleGenAI } = require('@google/genai');
const database = require('./database');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const JWT_SECRET = process.env.JWT_SECRET || 'fallback-secret';

// --- AUTH ---
app.post('/api/auth/login', async (req, res) => {
    try {
        const { loginId, password } = req.body;
        const { account, role } = await database.findAccountForLogin(loginId);
        if (account && account.password === password) {
            const token = jwt.sign({ id: account.id, role }, JWT_SECRET, { expiresIn: '1d' });
            return res.json({ token, role, account });
        }
        res.status(401).json({ message: 'Invalid credentials.' });
    } catch (e) { res.status(500).json({ message: e.message }); }
});

app.get('/api/auth/verify', authMiddleware, async (req, res) => {
    try {
        const account = await database.findAccountById(req.user.id, req.user.role.toLowerCase() + 's');
        if (!account) return res.status(404).send();
        res.json({ account, role: req.user.role });
    } catch (e) { res.status(500).send(); }
});

// --- USER ---
app.get('/api/user/data', authMiddleware, async (req, res) => {
    if (req.user.role !== 'USER') return res.sendStatus(403);
    const games = await database.getAllFromTable('games');
    const allBets = await database.getAllFromTable('bets');
    const userBets = allBets.filter(b => b.userId === req.user.id).sort((a,b) => new Date(b.timestamp) - new Date(a.timestamp));
    res.json({ games, bets: userBets });
});

app.post('/api/user/bets', authMiddleware, async (req, res) => {
    if (req.user.role !== 'USER') return res.sendStatus(403);
    const { gameId, betGroups } = req.body;
    try {
        // Simple betting logic restored
        const user = await database.findAccountById(req.user.id, 'users');
        const game = await database.findAccountById(gameId, 'games');
        if (!game.isMarketOpen) return res.status(400).json({ message: "Market closed" });

        let cost = 0;
        betGroups.forEach(g => cost += (g.numbers.length * g.amountPerNumber));
        if (user.wallet < cost) return res.status(400).json({ message: "Insufficient balance" });

        for (const group of betGroups) {
            const bid = uuidv4();
            await database.run('INSERT INTO bets VALUES (?,?,?,?,?,?,?,?,?)',
                [bid, user.id, user.dealerId, gameId, group.subGameType, JSON.stringify(group.numbers), group.amountPerNumber, group.numbers.length * group.amountPerNumber, new Date().toISOString()]);
        }
        await database.addLedgerEntry(user.id, 'USER', `Bet on ${game.name}`, cost, 0);
        res.status(201).json({ success: true });
    } catch (e) { res.status(500).json({ message: e.message }); }
});

// --- DEALER ---
app.get('/api/dealer/data', authMiddleware, async (req, res) => {
    if (req.user.role !== 'DEALER') return res.sendStatus(403);
    const users = (await database.getAllFromTable('users', true)).filter(u => u.dealerId === req.user.id);
    const bets = (await database.getAllFromTable('bets')).filter(b => b.dealerId === req.user.id);
    res.json({ users, bets });
});

app.post('/api/dealer/topup/user', authMiddleware, async (req, res) => {
    if (req.user.role !== 'DEALER') return res.sendStatus(403);
    const { userId, amount } = req.body;
    try {
        const dealer = await database.findAccountById(req.user.id, 'dealers');
        if (dealer.wallet < amount) return res.status(400).json({ message: "Insufficient Dealer Balance" });
        await database.addLedgerEntry(req.user.id, 'DEALER', `Topup for ${userId}`, amount, 0);
        await database.addLedgerEntry(userId, 'USER', `Topup from Dealer`, 0, amount);
        res.json({ success: true });
    } catch (e) { res.status(500).json({ message: e.message }); }
});

// --- ADMIN ---
app.get('/api/admin/data', authMiddleware, async (req, res) => {
    if (req.user.role !== 'ADMIN') return res.sendStatus(403);
    res.json({
        dealers: await database.getAllFromTable('dealers', true),
        users: await database.getAllFromTable('users', true),
        games: await database.getAllFromTable('games'),
        bets: await database.getAllFromTable('bets')
    });
});

app.post('/api/admin/games/:id/declare-winner', authMiddleware, async (req, res) => {
    if (req.user.role !== 'ADMIN') return res.sendStatus(403);
    const { winningNumber } = req.body;
    await database.run('UPDATE games SET winningNumber = ? WHERE id = ?', [winningNumber, req.params.id]);
    res.json({ success: true });
});

// --- PUBLIC ---
app.get('/api/games', async (req, res) => {
    const games = await database.getAllFromTable('games');
    res.json(games);
});

const PORT = process.env.PORT || 3001;
database.connect();
database.verifySchema().then(() => {
    app.listen(PORT, () => console.error(`>>> A-BABA SERVER RUNNING ON PORT ${PORT} <<<`));
});

