            CREATE TABLE number_limits (id SERIAL PRIMARY KEY, gametype TEXT NOT NULL, numbervalue TEXT NOT NULL, limitamount NUMERIC(20,2) NOT NULL, UNIQUE(gametype, numbervalue));
        `;

        await client.query(schema);
