@tailwind base;
@tailwind components;
@tailwind utilities;

html {
  scroll-behavior: smooth;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Russo One', sans-serif;
  background-color: #020617; /* slate-950 */
  touch-action: pan-y; /* Improve mobile scroll */
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.animated-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  z-index: -1;
  background-color: #020617;
  /* Grid animation and background-image removed for solid color layout */
}

/* Custom Scrollbar - Now applied to the whole document */
html::-webkit-scrollbar { width: 8px; }
html::-webkit-scrollbar-track { background: #0f172a; }
html::-webkit-scrollbar-thumb { background-color: #0891b2; border-radius: 20px; border: 2px solid #0f172a; }

/* Custom Scrollbar for mobile-scrollable elements */
.mobile-scroll-x {
  -webkit-overflow-scrolling: touch; /* Momentum scrolling on iOS */
}
.mobile-scroll-x::-webkit-scrollbar {
  height: 6px;
  width: 6px;
}
.mobile-scroll-x::-webkit-scrollbar-track {
  background: transparent;
}
.mobile-scroll-x::-webkit-scrollbar-thumb {
  background-color: rgba(8, 145, 178, 0.5); /* Semi-transparent cyan */
  border-radius: 20px;
}
.mobile-scroll-x:hover::-webkit-scrollbar-thumb {
  background-color: #0891b2; /* Solid cyan on hover */
}


/* Text Glitch Effect */
.glitch-text {
  position: relative;
  color: #67e8f9;
  text-shadow: 0 0 5px #0891b2, 0 0 10px #0891b2;
}
.glitch-text::before,
.glitch-text::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  overflow: hidden;
  clip: rect(0, 900px, 0, 0);
}
.glitch-text::before {
  left: 2px;
  text-shadow: -2px 0 #ec4899;
  animation: glitch-anim-1 2s infinite linear alternate-reverse;
}
.glitch-text::after {
  left: -2px;
  text-shadow: -2px 0 #34d399, 2px 2px #ec4899;
  animation: glitch-anim-2 3s infinite linear alternate-reverse;
}

@keyframes glitch-anim-1 {
  0% { clip: rect(42px, 9999px, 44px, 0); }
  5% { clip: rect(12px, 9999px, 60px, 0); }
  100% { clip: rect(90px, 9999px, 98px, 0); }
}
@keyframes glitch-anim-2 {
  0% { clip: rect(42px, 9999px, 44px, 0); }
  100% { clip: rect(10px, 9999px, 95px, 0); }
}

/* Animated Checkmark Icon for Bet Confirmation */
.animated-check {
  height: 4rem; /* 64px */
  width: 4rem;
}

.animated-check__circle {
  stroke-dasharray: 166;
  stroke-dashoffset: 166;
  stroke-width: 3;
  stroke-miterlimit: 10;
  stroke: #4ade80; /* Tailwind green-400 */
  fill: none;
  animation: stroke 0.6s cubic-bezier(0.65, 0, 0.45, 1) forwards;
}

.animated-check__check {
  transform-origin: 50% 50%;
  stroke-dasharray: 48;
  stroke-dashoffset: 48;
  stroke-width: 4;
  stroke-linecap: round;
  stroke: #4ade80; /* Tailwind green-400 */
  fill: none;
  animation: stroke 0.3s cubic-bezier(0.65, 0, 0.45, 1) 0.8s forwards;
}

@keyframes stroke {
  100% {
    stroke-dashoffset: 0;
  }
}

