    };

    return (
        <div className="bg-slate-800/50 p-4 rounded-lg border border-slate-700 flex flex-col">
            <div className="flex justify-between items-center mb-3">
                <h4 className={`text-lg font-semibold ${color}`}>{title}</h4>
