    for (const t of [{n:'users',r:'USER'},{n:'dealers',r:'DEALER'},{n:'admins',r:'ADMIN'}]) {
        const account = db.prepare(`SELECT * FROM ${t.n} WHERE lower(id) = ?`).get(lowerId);
        if (account) return { account, role: t.r };
    }
