        if (initialDeposit > 0) {
            topUpUserWallet(dealerId, userData.id, initialDeposit);
        }
        newUser = findAccountById(userData.id, 'users');
    });
    return newUser;
};

const updateUser = (userData, id, dealerId) => {
    db.prepare('UPDATE users SET name = ?, password = ?, area = ?, contact = ?, commissionRate = ?, prizeRates = ?, betLimits = ?, avatarUrl = ? WHERE id = ? AND dealerId = ?')
      .run(userData.name, userData.password, userData.area, userData.contact, userData.commissionRate, JSON.stringify(userData.prizeRates), userData.betLimits ? JSON.stringify(userData.betLimits) : null, userData.avatarUrl, id, dealerId);
    return findAccountById(id, 'users');
};

const updateDealer = (dealerData, id) => {
    db.prepare('UPDATE dealers SET name = ?, password = ?, area = ?, contact = ?, commissionRate = ?, prizeRates = ?, avatarUrl = ? WHERE id = ?')
      .run(dealerData.name, dealerData.password, dealerData.area, dealerData.contact, dealerData.commissionRate, JSON.stringify(dealerData.prizeRates), dealerData.avatarUrl, id);
    return findAccountById(id, 'dealers');
};

const getFinancialSummary = () => {
    const summary = {
        games: [],
        totals: {
            totalStake: 0,
            totalPayouts: 0,
            totalDealerProfit: 0,
            totalCommissions: 0,
            netProfit: 0
        },
        totalBets: 0
    };

    const games = db.prepare('SELECT * FROM games').all();
    const bets = db.prepare('SELECT * FROM bets').all();
    summary.totalBets = bets.length;

    games.forEach(game => {
        const gameBets = bets.filter(b => b.gameId === game.id);
        const gameStake = gameBets.reduce((sum, b) => sum + b.totalAmount, 0);

        // This is a simplified simulation for the summary dashboard
        // Real logic would aggregate payouts based on winning numbers
        summary.games.push({
            gameName: game.name,
            winningNumber: game.winningNumber || 'Pending',
            totalStake: gameStake,
            totalPayouts: 0, // Would be calculated from ledger entries tagged with gameId
            totalDealerProfit: 0,
            totalCommissions: 0,
            netProfit: gameStake
        });

        summary.totals.totalStake += gameStake;
    });

    summary.totals.netProfit = summary.totals.totalStake;
    return summary;
};

const getLiveBooking = (gameId) => {
    const bets = db.prepare('SELECT * FROM bets WHERE gameId = ?').all(gameId).map(b => {
        b.numbers = JSON.parse(b.numbers);
        return b;
    });
    return bets;
};

const getNumberSummary = (gameId, dealerId, date) => {
    const query = `
        SELECT b.numbers, b.amountPerNumber, b.subGameType
        FROM bets b
        WHERE (b.gameId = ? OR ? IS NULL)
        AND (b.dealerId = ? OR ? IS NULL)
        AND (date(b.timestamp) = ? OR ? IS NULL)
    `;
    const bets = db.prepare(query).all(gameId || null, gameId || null, dealerId || null, dealerId || null, date || null, date || null);

    const result = {
        twoDigit: [],
        oneDigitOpen: [],
        oneDigitClose: []
    };

    const aggregate = (type, list) => {
        const map = new Map();
        list.forEach(b => {
            const nums = JSON.parse(b.numbers);
            nums.forEach(n => {
                map.set(n, (map.get(n) || 0) + b.amountPerNumber);
            });
        });
        return Array.from(map.entries())
            .map(([number, stake]) => ({ number, stake }))
            .sort((a, b) => b.stake - a.stake);
    };

    result.twoDigit = aggregate('2 Digit', bets.filter(b => b.subGameType === '2 Digit'));
    result.oneDigitOpen = aggregate('1 Digit Open', bets.filter(b => b.subGameType === '1 Digit Open'));
    result.oneDigitClose = aggregate('1 Digit Close', bets.filter(b => b.subGameType === '1 Digit Close'));

    return result;
};

module.exports = {
    connect, verifySchema, findAccountById, findAccountForLogin,
    getAllFromTable, findUsersByDealerId, findBetsByDealerId,
    runInTransaction, addLedgerEntry, createUser, updateUser, updateDealer,
    topUpUserWallet, withdrawFromUserWallet, placeBulkBets,
    getFinancialSummary, getLiveBooking, getNumberSummary,
    toggleUserRestrictionByDealer: (id, dealerId) => {
        db.prepare('UPDATE users SET isRestricted = 1 - isRestricted WHERE id = ? AND dealerId = ?').run(id, dealerId);
        return findAccountById(id, 'users');
    },
    toggleAccountRestriction: (id, table) => {
        db.prepare(`UPDATE ${table} SET isRestricted = 1 - isRestricted WHERE id = ?`).run(id);
        return findAccountById(id, table);
    },
    updateDrawTime: (gameId, time) => {
        db.prepare('UPDATE games SET drawTime = ? WHERE id = ?').run(time, gameId);
    }
};

