        gameId: string;
        betGroups: { subGameType: SubGameType; numbers: string[]; amountPerNumber: number }[];
    } | {
        isMultiGame: true;
        multiGameBets: Map<string, { gameName: string, betGroups: { subGameType: SubGameType; numbers: string[]; amountPerNumber: number }[] }>;
    }) => void;
