@tailwind base;
@tailwind components;
@tailwind utilities;

html {
  scroll-behavior: smooth;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Russo One', sans-serif;
  background-color: #1a0505;
  touch-action: pan-y;
  overflow-x: hidden;
  color: #fce7e7;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.animated-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  z-index: -1;
  background-color: #1a0505;
  background-image: 
    linear-gradient(rgba(225, 29, 72, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(225, 29, 72, 0.05) 1px, transparent 1px);
  background-size: 50px 50px;
  animation: pan-grid 120s linear infinite;
}

@keyframes pan-grid {
  0% { background-position: 0 0; }
  100% { background-position: 1000px 1000px; }
}

@keyframes slide-in {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes fade-in {
  from { opacity: 0; transform: scale(0.98) translateY(-5px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.animate-slide-in {
  animation: slide-in 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.animate-fade-in {
  animation: fade-in 0.3s ease-out forwards;
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}

.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Red & Rose Quartz Glitch Effect */
.glitch-text {
  position: relative;
  color: #fb7185; /* rose-400 */
  text-shadow: 0 0 8px rgba(225, 29, 72, 0.6);
}
.glitch-text::before,
.glitch-text::after {
  content: attr(data-text);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  overflow: hidden;
  clip: rect(0, 900px, 0, 0);
}
.glitch-text::before {
  left: 2px;
  text-shadow: -2px 0 #991b1b; /* red-800 */
  animation: glitch-anim-1 2s infinite linear alternate-reverse;
}
.glitch-text::after {
  left: -2px;
  text-shadow: -2px 0 #f472b6; /* pink-400 */
  animation: glitch-anim-2 3s infinite linear alternate-reverse;
}

@keyframes glitch-anim-1 {
  0% { clip: rect(15px, 9999px, 20px, 0); }
  20% { clip: rect(45px, 9999px, 50px, 0); }
  60% { clip: rect(10px, 9999px, 12px, 0); }
  100% { clip: rect(85px, 9999px, 95px, 0); }
}
@keyframes glitch-anim-2 {
  0% { clip: rect(5px, 9999px, 10px, 0); }
  40% { clip: rect(60px, 9999px, 65px, 0); }
  80% { clip: rect(30px, 9999px, 35px, 0); }
  100% { clip: rect(70px, 9999px, 75px, 0); }
}

.mobile-scroll-x {
  scrollbar-width: thin;
  scrollbar-color: #e11d48 transparent;
}

.mobile-scroll-x::-webkit-scrollbar {
  height: 4px;
}
.mobile-scroll-x::-webkit-scrollbar-thumb {
  background-color: #e11d48;
  border-radius: 10px;
}

.animated-check__circle {
  stroke-dasharray: 166;
  stroke-dashoffset: 166;
  stroke-width: 2;
  stroke-miterlimit: 10;
  stroke: #f43f5e;
  fill: none;
  animation: stroke 0.6s cubic-bezier(0.65, 0, 0.45, 1) forwards;
}

.animated-check {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  display: block;
  stroke-width: 2;
  stroke: #fff;
  stroke-miterlimit: 10;
  margin: 10% auto;
  box-shadow: inset 0px 0px 0px #f43f5e;
  animation: fill .4s ease-in-out .4s forwards, scale .3s ease-in-out .9s both;
}

.animated-check__check {
  transform-origin: 50% 50%;
  stroke-dasharray: 48;
  stroke-dashoffset: 48;
  animation: stroke 0.3s cubic-bezier(0.65, 0, 0.45, 1) 0.8s forwards;
}

@keyframes stroke {
  100% { stroke-dashoffset: 0; }
}
@keyframes scale {
  0%, 100% { transform: none; }
  50% { transform: scale3d(1.1, 1.1, 1); }
}
@keyframes fill {
  100% { box-shadow: inset 0px 0px 0px 30px #f43f5e; }
}

import React, { useState } from 'react';
import { Game } from '../types';
import { useCountdown } from '../hooks/useCountdown';
import { Icons, GAME_LOGOS } from '../constants';
import { useAuth } from '../hooks/useAuth';

const formatTime12h = (time24: string) => {
    const [hours, minutes] = time24.split(':').map(Number);
    const ampm = hours >= 12 ? 'PM' : 'AM';
    const hours12 = hours % 12 || 12;
    return `${String(hours12).padStart(2, '0')}:${String(minutes).padStart(2, '0')} ${ampm}`;
};

const GameDisplayCard: React.FC<{ game: Game; onClick: () => void }> = ({ game, onClick }) => {
    const { status, text: countdownText } = useCountdown(game.drawTime);
    const hasFinalWinner = !!game.winningNumber && !game.winningNumber.endsWith('_');
    const isMarketClosedForDisplay = !game.isMarketOpen;
    const themeColor = hasFinalWinner ? 'rose- quartz' : 'red';
    const logo = GAME_LOGOS[game.name] || '';

    return (
        <button
            onClick={onClick}
            className={`relative group bg-evening-red-950/40 p-6 flex flex-col items-center justify-between text-center transition-all duration-500 ease-in-out border border-rose-900/30 w-full overflow-hidden focus:outline-none focus:ring-2 focus:ring-rose-500`}
            style={{
                clipPath: 'polygon(0 15px, 15px 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%)',
            }}
        >
            <div className={`absolute -inset-0.5 bg-gradient-to-r from-red-600 to-rose-400 rounded-lg blur opacity-0 group-hover:opacity-40 transition duration-700`}></div>
            <div className="relative z-10 w-full flex flex-col h-full">
                <div className="flex-grow">
                    <img src={logo} alt={`${game.name} logo`} className="w-20 h-20 rounded-full mb-4 border-2 border-rose-900/50 group-hover:border-rose-400 transition-colors mx-auto shadow-lg shadow-black/50" />
                    <h3 className="text-xl text-rose-100 mb-1 uppercase tracking-widest font-bold">{game.name}</h3>
                    <p className="text-rose-400/60 text-xs font-sans">DRAW AT {formatTime12h(game.drawTime)}</p>
                </div>
                <div className={`text-center w-full p-2 mt-4 bg-black/40 border-t border-rose-500/20 min-h-[85px] flex flex-col justify-center rounded-sm`}>
                    {hasFinalWinner ? (
                        <>
                            <div className="text-[9px] uppercase tracking-[0.4em] text-rose-400 font-black mb-1">FINAL RESULT</div>
                            <div className="text-4xl font-mono font-bold text-white drop-shadow-[0_0_12px_rgba(244,63,94,0.7)]">
                                {game.winningNumber}
                            </div>
                        </>
                    ) : isMarketClosedForDisplay ? (
                        <>
                            <div className="text-[10px] uppercase tracking-widest text-red-500/70 font-bold">MARKET STATUS</div>
                            <div className="text-xl font-mono font-bold text-red-600">CLOSED</div>
                        </>
                    ) : status === 'OPEN' ? (
                        <>
                            <div className="text-[10px] uppercase tracking-widest text-rose-300/50 mb-1">CLOSING IN</div>
                            <div className="text-2xl font-mono font-bold text-red-500">{countdownText}</div>
                        </>
                    ) : (
                        <>
                            <div className="text-[10px] uppercase tracking-widest text-rose-300/50 mb-1">OPENS AT</div>
                            <div className="text-lg font-mono font-bold text-rose-500/60">{countdownText}</div>
                        </>
                    )}
                </div>
            </div>
        </button>
    );
};

