const TENSION_PHRASES = [
    "DECRYPTING FREQUENCIES...",
    "CALCULATING PROBABILITY...",
    "HARVESTING DATA CORES...",
    "SYNCHRONIZING REELS...",
    "ISOLATING JACKPOT VECTOR...",
