const ResultRevealOverlay: React.FC<ResultRevealOverlayProps> = ({ gameName, winningNumber, onClose }) => {
  const [phase, setPhase] = useState<'ROLLING' | 'REVEAL'>('ROLLING');
  const [displayNum, setDisplayNum] = useState('00');
  const [isShaking, setIsShaking] = useState(false);
  const [phraseIndex, setPhraseIndex] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [showFlash, setShowFlash] = useState(false);

  const TOTAL_ROLL_TIME = 15000; // Faster tension for better UX

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    let phraseInterval: ReturnType<typeof setInterval>;
    let progressInterval: ReturnType<typeof setInterval>;

    if (phase === 'ROLLING') {
      interval = setInterval(() => {
        const randomNum = winningNumber.length === 1 
          ? Math.floor(Math.random() * 10).toString()
          : Math.floor(Math.random() * 100).toString().padStart(2, '0');
        setDisplayNum(randomNum);
      }, 45);

      phraseInterval = setInterval(() => {
        setPhraseIndex(prev => (prev + 1) % TENSION_PHRASES.length);
      }, 2000);

      progressInterval = setInterval(() => {
        setElapsed(prev => prev + 100);
      }, 100);

      const timer = setTimeout(() => {
        setShowFlash(true);
        setTimeout(() => {
            setPhase('REVEAL');
            setDisplayNum(winningNumber);
            setIsShaking(true);
            setShowFlash(false);
            setTimeout(() => setIsShaking(false), 600);
        }, 100);
      }, TOTAL_ROLL_TIME);

      return () => {
        clearInterval(interval);
        clearInterval(phraseInterval);
        clearInterval(progressInterval);
        clearTimeout(timer);
      };
    }
  }, [phase, winningNumber]);

  const intensity = elapsed / TOTAL_ROLL_TIME;

  return (
    <div className={`fixed inset-0 z-[1000] flex flex-col items-center overflow-hidden bg-[#0a0202] transition-all duration-1000 py-10 justify-center ${isShaking ? 'animate-shake scale-110' : ''}`}>

      <div className="fixed inset-0 flex items-center justify-center overflow-hidden pointer-events-none">
        <div 
            className="w-[300vw] h-[300vw] opacity-30"
            style={{ 
                animation: `spin ${10 - (intensity * 8)}s linear infinite`,
                background: `conic-gradient(from 0deg, 
                    transparent 0deg, 
                    rgba(225,29,72,0.4) 15deg, 
                    transparent 30deg, 
                    rgba(244,114,182,0.3) 60deg, 
                    transparent 90deg, 
                    rgba(159,18,57,0.4) 120deg, 
                    transparent 150deg)`
            }}
        ></div>
        <div className={`absolute inset-0 transition-colors duration-1000 ${intensity > 0.8 ? 'bg-red-600/10' : 'bg-rose-900/5'}`}></div>
      </div>

      {showFlash && <div className="fixed inset-0 bg-rose-100 z-[1100]"></div>}
      {phase === 'REVEAL' && <Confetti />}

      <div className="relative z-[1010] text-center px-4 w-full max-w-4xl flex flex-col items-center">
        <div className="mb-12 w-full">
            <h2 className={`text-xs md:text-xl font-black tracking-[1em] uppercase transition-all duration-1000 ${phase === 'REVEAL' ? 'text-red-500 drop-shadow-[0_0_20px_rgba(220,38,38,0.9)]' : 'text-rose-200/40'}`}>
                {phase === 'REVEAL' ? 'TRANSMISSION COMPLETE' : TENSION_PHRASES[phraseIndex]}
            </h2>
            <div className="h-1 w-48 md:w-64 mx-auto mt-6 bg-rose-950 rounded-full overflow-hidden border border-rose-900/20">
                <div 
                    className={`h-full transition-all duration-100 ease-linear bg-gradient-to-r from-red-600 to-rose-400`} 
                    style={{ width: phase === 'REVEAL' ? '100%' : `${intensity * 100}%` }}
                ></div>
            </div>
        </div>

        <h1 className={`text-5xl md:text-8xl font-black uppercase tracking-tighter mb-12 transition-all duration-1000 ${phase === 'REVEAL' ? 'text-white scale-110' : 'text-rose-950'}`}>
          {gameName}
        </h1>

        <div className="relative inline-block">
            <div className={`absolute -inset-16 rounded-full blur-[80px] transition-all duration-1000 ${phase === 'REVEAL' ? 'bg-red-600/60 scale-150' : intensity > 0.8 ? 'bg-red-900/40 animate-pulse' : 'bg-rose-950/20'}`}></div>

            <div className={`
                w-56 h-56 md:w-80 md:h-80 rounded-full border-[8px] md:border-[12px] relative flex items-center justify-center transition-all duration-1000 overflow-hidden
                ${phase === 'REVEAL' 
                    ? 'border-white bg-gradient-to-br from-red-600 via-rose-900 to-black shadow-[0_0_80px_rgba(220,38,38,0.9)]' 
                    : intensity > 0.8 
                    ? 'border-red-900 bg-black shadow-[0_0_40px_rgba(153,27,27,0.4)]'
                    : 'border-rose-950 bg-black'}
            `}>
                <div className={`
                    text-8xl md:text-[10rem] font-black font-mono tracking-tighter transition-all duration-200
                    ${phase === 'REVEAL' ? 'text-white drop-shadow-[0_0_25px_rgba(255,255,255,0.8)]' : 'text-red-950'}
                `}>
                    {displayNum}
                </div>
            </div>

            {phase === 'REVEAL' && (
                <>
                    <div className="absolute -inset-4 md:-inset-8 border-4 border-white/30 rounded-full animate-ping"></div>
                    <div className="absolute -inset-10 md:-inset-16 border-2 border-red-500/20 rounded-full animate-[ping_3s_linear_infinite]"></div>
                </>
            )}
        </div>

        <div className="mt-16 h-40 flex flex-col items-center justify-center z-[1200]">
          {phase === 'REVEAL' ? (
            <div className="animate-reveal-slam-intense flex flex-col items-center">
              <div className="text-3xl md:text-5xl font-black text-white uppercase italic tracking-[0.3em] mb-8 text-center drop-shadow-xl">
                WINNER REVEALED
              </div>
              <button 
                onClick={onClose}
                className="group relative px-12 py-5 rounded-2xl overflow-hidden transition-all transform hover:scale-110 active:scale-95 bg-white shadow-2xl"
              >
                <span className="relative z-10 text-black font-black text-xl tracking-widest uppercase">Continue</span>
                <div className="absolute inset-0 bg-gradient-to-r from-red-600 to-rose-400 translate-x-[-100%] group-hover:translate-x-0 transition-transform duration-500"></div>
              </button>
            </div>
          ) : (
            <div className="space-y-4">
                <div className="flex gap-4 justify-center">
                    <div className="w-2 h-2 rounded-full animate-bounce bg-red-600 shadow-[0_0_10px_#dc2626]"></div>
                    <div className="w-2 h-2 rounded-full animate-bounce bg-red-600 shadow-[0_0_10px_#dc2626]" style={{animationDelay: '0.1s'}}></div>
                    <div className="w-2 h-2 rounded-full animate-bounce bg-red-600 shadow-[0_0_10px_#dc2626]" style={{animationDelay: '0.2s'}}></div>
                </div>
                <div className="text-rose-100/30 text-[10px] font-mono uppercase tracking-[0.6em]">
                    CALIBRATING SENSORS... {(intensity * 100).toFixed(0)}%
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

