    return (
        <div className={`bg-evening-red-950/40 rounded-3xl shadow-xl p-6 flex flex-col justify-between transition-all duration-500 border border-rose-900/20 group ${!isPlayable ? 'opacity-60' : 'hover:border-rose-500/50 hover:-translate-y-2'}`}>
