const BettingTerminalView: React.FC<{ users: User[]; games: Game[]; placeBetAsDealer: (details: any) => Promise<void> }> = ({ users, games, placeBetAsDealer }) => {
    const [selectedUserId, setSelectedUserId] = useState('');
    const [selectedGameId, setSelectedGameId] = useState('');
    const [bulkInput, setBulkInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    const handleProcessBets = async () => {
        if (!selectedUserId || !selectedGameId || !bulkInput) return;
        setIsLoading(true);
        try {
            const lines = bulkInput.split('\n').filter(l => l.trim());
            const betGroups: any[] = [];
            lines.forEach(line => {
                const stakeMatch = line.match(/(?:rs|r)\s*(\d+\.?\d*)/i);
                const stake = stakeMatch ? parseFloat(stakeMatch[1]) : 0;
                if (stake <= 0) return;
                const numbersPart = line.substring(0, stakeMatch!.index).trim();
                const numbers = numbersPart.split(/[-.,\s]+/).filter(n => n.length > 0);
                if (numbers.length > 0) {
                    betGroups.push({ subGameType: SubGameType.TwoDigit, numbers, amountPerNumber: stake });
                }
            });
            if (betGroups.length === 0) { alert("Format Error: use '14, 25 rs100'"); setIsLoading(false); return; }
            await placeBetAsDealer({ userId: selectedUserId, gameId: selectedGameId, betGroups });
            setBulkInput('');
            alert("Terminal synchronization successful.");
        } catch (error: any) {
            alert("Encryption rejected.");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="bg-evening-red-950/40 p-8 rounded-3xl border border-rose-900/20 shadow-2xl">
            <h3 className="text-xl font-black text-rose-50 uppercase tracking-[0.2em] mb-8">Rapid Entry Terminal</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-6">
                <select value={selectedUserId} onChange={e => setSelectedUserId(e.target.value)} className="bg-black/60 text-rose-100 p-4 rounded-xl border border-rose-900/30 text-[10px] font-black uppercase tracking-widest focus:border-red-600 focus:outline-none appearance-none">
                    <option value="">Choose Agent</option>
                    {Array.isArray(users) && users.filter(u => !u.isRestricted).map(u => <option key={u.id} value={u.id}>{u.name} ({u.id})</option>)}
                </select>
                <select value={selectedGameId} onChange={e => setSelectedGameId(e.target.value)} className="bg-black/60 text-rose-100 p-4 rounded-xl border border-rose-900/30 text-[10px] font-black uppercase tracking-widest focus:border-red-600 focus:outline-none appearance-none">
                    <option value="">Target Market</option>
                    {Array.isArray(games) && games.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                </select>
            </div>
            <textarea rows={8} value={bulkInput} onChange={e => setBulkInput(e.target.value)} placeholder="PROTOCOL ENTRY:&#10;14, 25, 33 rs50&#10;88, 91 rs100" className="w-full bg-black/60 text-rose-400 p-6 rounded-2xl border border-rose-900/30 font-mono text-sm focus:border-red-600 focus:outline-none placeholder-rose-950 shadow-inner" />
            <div className="flex justify-end mt-8">
                <button onClick={handleProcessBets} disabled={!selectedUserId || !selectedGameId || !bulkInput || isLoading} className="w-full md:w-auto bg-red-600 hover:bg-red-500 text-white font-black py-4 px-12 rounded-2xl disabled:opacity-30 transition-all uppercase tracking-[0.3em] text-xs shadow-xl shadow-red-950/40">
                    {isLoading ? 'SYNCING...' : 'INITIATE TRANSFER'}
                </button>
            </div>
        </div>
    );
};

