    const logo = GAME_LOGOS[game.name] || '';

    return (
        <div className="group relative circular-game-card">
            {/* Pulsing ring for active games */}
            {!hasResult && !isClosed && countdown.status === 'OPEN' && (
                <div className="absolute inset-0 border border-accent-indigo/30 rounded-full animate-ping opacity-20"></div>
