            <div className="card w-full max-w-xl bg-[#020617] p-0 overflow-hidden border-slate-800 shadow-[0_40px_100px_-20px_rgba(0,0,0,0.8)]">
                <div className="p-8 bg-slate-900/50 flex justify-between items-center border-b border-slate-800">
                    <div className="flex items-center gap-5">
                        <img src={selectedGame.logo} className="w-12 h-12 rounded-full border border-slate-700 bg-slate-900 p-1" alt="" />
                        <div>
                            <h3 className="text-xl font-bold text-white uppercase tracking-wider">TRADE: {selectedGame.name}</h3>
                            <p className="text-[9px] font-bold text-slate-600 uppercase tracking-[0.4em] mt-1">Terminal Execution Mode</p>
                        </div>
                    </div>
                    <button onClick={() => setSelectedGame(null)} className="p-3 text-slate-600 hover:text-white transition-colors">{Icons.close}</button>
                </div>
                <div className="p-8 sm:p-12 space-y-10">
                    <div className="flex flex-wrap justify-center gap-3">
                        {[SubGameType.OneDigitOpen, SubGameType.OneDigitClose, SubGameType.TwoDigit].map(t => (
                            <button key={t} onClick={() => setBetType(t)} className={`px-6 py-3 rounded-full text-[10px] font-bold uppercase transition-all ${betType === t ? 'bg-accent-indigo text-white' : 'bg-slate-900 text-slate-500'}`}>{t}</button>
                        ))}
                    </div>
                    <div className="space-y-8">
                        <div className="space-y-3">
                             <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block text-center">Numbers</label>
                             <input type="text" value={inputNumbers} onChange={e => setInputNumbers(e.target.value)} placeholder="14, 25, 33" className="text-center text-4xl sm:text-6xl font-mono font-bold py-10 tracking-[0.2em]" />
                        </div>
                        <div className="space-y-3">
                             <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block text-center">Unit Stake</label>
                             <input type="number" value={amountPerNumber || ''} onChange={e => setAmountPerNumber(parseFloat(e.target.value) || 0)} placeholder="PKR" className="text-center text-4xl sm:text-6xl font-mono font-bold py-10 text-accent-indigo" />
                        </div>

                        <div className="grid grid-cols-2 gap-6">
                            <div className="bg-black/30 p-6 rounded-2xl text-center border border-slate-900">
                                <p className="text-[10px] text-slate-600 font-bold uppercase mb-1">Total</p>
                                <p className="text-xl sm:text-3xl font-mono font-bold text-white tracking-tighter">PKR {totalStake.toLocaleString()}</p>
                            </div>
                            <div className="bg-black/30 p-6 rounded-2xl text-center border border-slate-900">
                                <p className="text-[10px] text-slate-600 font-bold uppercase mb-1">Items</p>
                                <p className="text-xl sm:text-3xl font-mono font-bold text-white tracking-tighter">{parsedNumbers.length}</p>
                            </div>
                        </div>
                    </div>

                    {errorMsg && <div className="text-center text-rose-500 font-bold text-xs uppercase tracking-widest py-3 bg-rose-500/5 rounded-xl border border-rose-500/10">{errorMsg}</div>}

                    <button onClick={handleCommitBet} disabled={isSubmitting || !totalStake} className="btn-primary w-full py-6 text-sm">
                        {isSubmitting ? 'Processing...' : 'Execute Transaction'}
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

interface UserPanelProps {
  user: User;
  games: Game[];
  bets: Bet[];
  placeBet: (details: any) => Promise<void>;
}

export default UserPanel;

