    return (
        <div className="bg-accent-indigo/10 border-b border-white/5 py-3 overflow-hidden backdrop-blur-xl">
            <div className="flex whitespace-nowrap animate-marquee">
                {[...activeWinners, ...activeWinners].map((game, i) => (
                    <div key={i} className="flex items-center px-12 border-r border-white/5">
