const UserPanel: React.FC<UserPanelProps> = ({ user, games, bets, placeBet }) => {
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [betType, setBetType] = useState<SubGameType>(SubGameType.TwoDigit);
  const [inputNumbers, setInputNumbers] = useState('');
  const [amountPerNumber, setAmountPerNumber] = useState<number>(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  const parsedNumbers = useMemo(() => {
    return inputNumbers.split(/[\s,.-]+/).filter(n => n.length > 0);
  }, [inputNumbers]);

  const totalStake = useMemo(() => {
    return parsedNumbers.length * (amountPerNumber || 0);
  }, [parsedNumbers, amountPerNumber]);

  const handleCommitBet = async () => {
    if (!selectedGame || parsedNumbers.length === 0 || amountPerNumber <= 0) {
      setErrorMsg('INCOMPLETE_DATA'); return;
    }
    if (totalStake > user.wallet) {
      setErrorMsg('LOW_LIQUIDITY'); return;
    }
    setIsSubmitting(true);
    setErrorMsg('');
    try {
      await placeBet({ gameId: selectedGame.id, betGroups: [{ subGameType: betType, numbers: parsedNumbers, amountPerNumber: amountPerNumber }] });
      setSelectedGame(null); setInputNumbers(''); setAmountPerNumber(0);
    } catch (err: any) {
      setErrorMsg(err.message || 'LINK_FAILURE');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-6 sm:p-12 space-y-12 sm:space-y-20 animate-fade-in relative pb-40">

      {/* Wallet / Stats Card */}
      <div className="card flex flex-col md:flex-row justify-between items-center gap-10 sm:gap-16 px-10 sm:px-16 py-10 sm:py-16 relative overflow-hidden shadow-2xl border-white/5">
        <div className="absolute top-0 right-0 w-64 h-64 bg-accent-indigo/5 blur-[120px] rounded-full"></div>

        <div className="flex flex-col sm:flex-row items-center gap-6 sm:gap-10 relative z-10 text-center sm:text-left">
            <div className="w-24 h-24 sm:w-32 sm:h-32 rounded-2xl bg-obsidian-900 border border-white/10 flex items-center justify-center font-bold text-accent-indigo text-4xl sm:text-6xl overflow-hidden shadow-inner">
               {user.avatarUrl ? <img src={user.avatarUrl} alt="" className="w-full h-full object-cover" /> : user.name.charAt(0)}
            </div>
            <div>
              <h2 className="text-3xl sm:text-6xl font-bold text-white tracking-tighter uppercase leading-none mb-3">{user.name}</h2>
              <div className="flex items-center justify-center sm:justify-start gap-3">
                  <span className="w-2.5 h-2.5 bg-accent-emerald rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.4)]"></span>
                  <p className="text-slate-500 text-[10px] sm:text-xs font-bold uppercase tracking-[0.6em]">{user.id}</p>
              </div>
            </div>
        </div>

        <div className="text-center md:text-right relative z-10 bg-obsidian-900/50 px-10 sm:px-14 py-8 rounded-2xl border border-white/5 shadow-inner w-full sm:w-auto">
            <p className="text-[10px] sm:text-xs font-bold text-slate-500 uppercase tracking-widest mb-1">Vault Liquidity</p>
            <p className="text-4xl sm:text-6xl lg:text-7xl font-bold text-white font-mono tracking-tighter">PKR {user.wallet.toLocaleString()}</p>
