                        </div>
                        <div className="space-y-3">
                             <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block text-center">Stake Volume</label>
                             <input type="number" value={amountPerNumber || ''} onChange={e => setAmountPerNumber(parseFloat(e.target.value) || 0)} placeholder="PKR" className="text-center text-4xl sm:text-6xl font-mono font-bold py-10 text-accent-indigo bg-obsidian-950 rounded-2xl border-white/5" />
                        </div>

                        <div className="grid grid-cols-2 gap-6">
                            <div className="bg-obsidian-950 p-6 rounded-2xl text-center border border-white/5">
                                <p className="text-[10px] text-slate-600 font-bold uppercase mb-1">Total Liability</p>
                                <p className="text-xl sm:text-3xl font-mono font-bold text-white tracking-tighter">PKR {totalStake.toLocaleString()}</p>
                            </div>
                            <div className="bg-obsidian-950 p-6 rounded-2xl text-center border border-white/5">
                                <p className="text-[10px] text-slate-600 font-bold uppercase mb-1">Quantity</p>
                                <p className="text-xl sm:text-3xl font-mono font-bold text-white tracking-tighter">{parsedNumbers.length}</p>
                            </div>
                        </div>
                    </div>

                    {errorMsg && <div className="text-center text-accent-rose font-bold text-xs uppercase tracking-widest py-3 bg-accent-rose/5 rounded-xl border border-accent-rose/10">{errorMsg}</div>}

                    <button onClick={handleCommitBet} disabled={isSubmitting || !totalStake} className="btn-primary w-full h-16 text-sm rounded-2xl">
                        {isSubmitting ? 'Authorizing...' : 'Establish Transaction'}
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

