import React, { useState } from 'react';
import { Game } from '../types';
import { useCountdown } from '../hooks/useCountdown';
import { Icons, GAME_LOGOS } from '../constants';
import { useAuth } from '../hooks/useAuth';

const formatTime12h = (time24: string) => {
    if (!time24) return '--:--';
    const [hours, minutes] = time24.split(':').map(Number);
    const ampm = hours >= 12 ? 'PM' : 'AM';
    const hours12 = hours % 12 || 12;
    return `${String(hours12).padStart(2, '0')}:${String(minutes).padStart(2, '0')} ${ampm}`;
};

const ResultsTicker: React.FC<{ games: Game[] }> = ({ games }) => {
    const activeWinners = games.filter(g => g.winningNumber && !g.winningNumber.endsWith('_'));
    if (activeWinners.length === 0) return null;

    return (
        <div className="bg-slate-900/50 border-b border-white/5 py-4 overflow-hidden backdrop-blur-xl">
            <div className="flex whitespace-nowrap animate-marquee">
                {[...activeWinners, ...activeWinners].map((game, i) => (
                    <div key={i} className="flex items-center px-12 sm:px-20 border-r border-white/5">
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest mr-6">{game.name}</span>
                        <span className="text-2xl sm:text-4xl font-mono font-black text-white tracking-tighter">{game.winningNumber}</span>
                    </div>
                ))}
            </div>
            <style>{`
                @keyframes marquee { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }
                .animate-marquee { animation: marquee 30s linear infinite; }
            `}</style>
        </div>
    );
};

const GameNodeOrb: React.FC<{ game: Game }> = ({ game }) => {
    const countdown = useCountdown(game.drawTime);
    const hasResult = !!game.winningNumber && !game.winningNumber.endsWith('_');
    const isClosed = !game.isMarketOpen;
    const logo = GAME_LOGOS[game.name] || '';

    return (
        <div className="group relative circular-game-card p-6 sm:p-10">
            {/* Pulsing ring for active sessions */}
            {!hasResult && !isClosed && countdown.status === 'OPEN' && (
                <div className="absolute inset-0 border border-accent-indigo/20 rounded-full animate-pulse-glow"></div>
            )}

            <div className="relative mb-4 sm:mb-6 w-16 h-16 sm:w-24 sm:h-24 z-10 shrink-0">
                <div className="absolute inset-0 bg-accent-indigo/10 blur-xl rounded-full opacity-0 group-hover:opacity-100 transition-opacity"></div>
                <img src={logo} alt={game.name} className="relative w-full h-full rounded-full border border-white/10 p-1 bg-slate-900 group-hover:scale-110 transition-transform duration-500" />
            </div>

            <div className="text-center relative z-10 w-full">
                <h3 className="text-xs sm:text-lg font-bold text-white mb-1 uppercase tracking-tight group-hover:text-accent-indigo transition-colors">{game.name}</h3>

                {hasResult ? (
                    <div className="mt-1">
                        <span className="text-[8px] uppercase tracking-widest text-accent-emerald font-black">WINNER</span>
                        <div className="text-xl sm:text-4xl font-mono font-black text-white leading-none tracking-tighter">{game.winningNumber}</div>
                    </div>
                ) : isClosed ? (
                    <div className="mt-3 py-1.5 px-4 bg-white/5 rounded-lg text-[9px] font-bold text-slate-500 uppercase tracking-widest">Market Closed</div>
                ) : (
                    <div className="mt-1">
                        <div className={`text-lg sm:text-3xl font-mono font-bold tracking-tighter leading-none ${countdown.status === 'OPEN' ? 'text-accent-indigo' : 'text-slate-600'}`}>
                            {countdown.text}
                        </div>
                        <div className="text-[8px] sm:text-[10px] uppercase tracking-widest text-slate-500 font-bold mt-2">
                           Draw @ {formatTime12h(game.drawTime)}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const LandingPage: React.FC<{ games: Game[] }> = ({ games }) => {
    const { login } = useAuth();
    const [loginId, setLoginId] = useState('');
    const [password, setPassword] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!loginId || !password) return;
        setIsSubmitting(true);
        setError(null);
        try {
            await login(loginId, password);
        } catch (err) {
            setError("AUTH_FAILURE: ACCESS DENIED");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="min-h-screen bg-obsidian flex flex-col">
            <ResultsTicker games={games} />

            <div className="max-w-7xl mx-auto px-6 sm:px-10 py-12 sm:py-24 w-full flex-grow relative overflow-hidden">
