const formatTime12h = (time24: string) => {
    if (!time24) return '--:--';
    const [hours, minutes] = time24.split(':').map(Number);
    const ampm = hours >= 12 ? 'PM' : 'AM';
    const hours12 = hours % 12 || 12;
    return `${String(hours12).padStart(2, '0')}:${String(minutes).padStart(2, '0')} ${ampm}`;
};

const GameOrbCard: React.FC<{ game: Game; onPlay: (game: Game) => void; isRestricted: boolean; }> = ({ game, onPlay, isRestricted }) => {
    const countdown = useCountdown(game.drawTime);
    const hasResult = !!game.winningNumber && !game.winningNumber.endsWith('_');
    const isPlayable = !!game.isMarketOpen && !isRestricted && countdown.status === 'OPEN';

    return (
        <button 
            onClick={() => onPlay(game)}
            disabled={!isPlayable}
            className={`group circular-game-card ${!isPlayable ? 'opacity-30 grayscale cursor-not-allowed' : 'hover:scale-105 active:scale-95 transition-transform duration-500'}`}
        >
            <div className="relative mb-3 sm:mb-5 w-16 h-16 sm:w-24 sm:h-24">
                <div className={`absolute -inset-4 rounded-full blur-2xl transition-all duration-700 ${isPlayable ? 'bg-accent-indigo/10 group-hover:bg-accent-indigo/20' : 'bg-transparent'}`}></div>
                <img src={game.logo} alt={game.name} className="relative w-full h-full rounded-full border border-white/10 p-1 bg-slate-900 group-hover:rotate-6 transition-transform duration-500" />
            </div>

            <div className="text-center px-2">
                <h3 className="font-bold text-slate-100 text-[10px] sm:text-base tracking-tight uppercase group-hover:text-accent-indigo transition-colors line-clamp-1">{game.name}</h3>

                {hasResult ? (
                    <div className="mt-1">
                        <span className="text-[7px] text-accent-emerald font-black tracking-widest uppercase">Result</span>
                        <div className="text-lg sm:text-3xl font-mono font-bold text-white leading-none tracking-tighter">{game.winningNumber}</div>
                    </div>
                ) : (
                    <div className="mt-1">
                        <div className={`text-base sm:text-2xl font-mono font-bold leading-tight tracking-tighter ${isPlayable ? 'text-accent-indigo' : 'text-slate-600'}`}>
                            {countdown.text}
                        </div>
                        <p className="text-[8px] sm:text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1 opacity-60">
                            {formatTime12h(game.drawTime)}
                        </p>
                    </div>
                )}
            </div>

            {isPlayable && (
                <div className="absolute -bottom-1 px-5 py-1.5 bg-accent-indigo text-white text-[9px] font-black rounded-full shadow-lg uppercase tracking-widest opacity-0 group-hover:opacity-100 translate-y-2 group-hover:translate-y-0 transition-all duration-300">
                    Trade
                </div>
            )}
        </button>
    );
};

