                                  <td className="p-6 text-right font-mono text-accent-rose font-bold text-lg">-{bet.totalAmount.toLocaleString()}</td>
                                  <td className="p-6 text-right">
                                      <span className="text-[9px] font-bold text-slate-600 uppercase tracking-widest italic">SECURE_SYNC</span>
                                  </td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </div>
      </div>

      {/* Trade Execution Modal */}
      {selectedGame && (
        <div className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
            <div className="card w-full max-w-xl bg-obsidian p-0 overflow-hidden border-white/5 shadow-[0_40px_100px_-20px_rgba(0,0,0,0.8)] rounded-[3rem]">
                <div className="p-8 bg-slate-900/50 flex justify-between items-center border-b border-white/5">
                    <div className="flex items-center gap-5">
                        <img src={selectedGame.logo} className="w-12 h-12 rounded-full border border-white/10 bg-slate-900 p-1" alt="" />
                        <div>
                            <h3 className="text-xl font-bold text-white uppercase tracking-wider">EXECUTE: {selectedGame.name}</h3>
                            <p className="text-[9px] font-bold text-slate-600 uppercase tracking-[0.4em] mt-1">Institutional Execution Terminal</p>
                        </div>
                    </div>
                    <button onClick={() => setSelectedGame(null)} className="p-3 text-slate-600 hover:text-white transition-colors">{Icons.close}</button>
                </div>
                <div className="p-8 sm:p-14 space-y-12">
                    <div className="flex flex-wrap justify-center gap-3">
                        {[SubGameType.OneDigitOpen, SubGameType.OneDigitClose, SubGameType.TwoDigit].map(t => (
                            <button key={t} onClick={() => setBetType(t)} className={`px-8 py-3 rounded-full text-[10px] font-bold uppercase transition-all ${betType === t ? 'bg-accent-indigo text-white shadow-lg' : 'bg-slate-900 text-slate-500 hover:bg-slate-800'}`}>{t}</button>
                        ))}
                    </div>
                    <div className="space-y-10">
                        <div className="space-y-3">
                             <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block text-center">Unit Identifiers</label>
                             <input type="text" value={inputNumbers} onChange={e => setInputNumbers(e.target.value)} placeholder="e.g. 14, 25, 33" className="text-center text-4xl sm:text-6xl font-mono font-bold py-10 tracking-[0.2em] bg-black/40 rounded-3xl" />
                        </div>
                        <div className="space-y-3">
                             <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block text-center">Stake Volume</label>
                             <input type="number" value={amountPerNumber || ''} onChange={e => setAmountPerNumber(parseFloat(e.target.value) || 0)} placeholder="PKR" className="text-center text-4xl sm:text-6xl font-mono font-bold py-10 text-accent-indigo bg-black/40 rounded-3xl" />
                        </div>

                        <div className="grid grid-cols-2 gap-6">
                            <div className="bg-black/30 p-8 rounded-3xl text-center border border-white/5">
                                <p className="text-[10px] text-slate-600 font-bold uppercase mb-1">Total Stake</p>
                                <p className="text-xl sm:text-3xl font-mono font-bold text-white tracking-tighter">PKR {totalStake.toLocaleString()}</p>
                            </div>
                            <div className="bg-black/30 p-8 rounded-3xl text-center border border-white/5">
                                <p className="text-[10px] text-slate-600 font-bold uppercase mb-1">Quantity</p>
                                <p className="text-xl sm:text-3xl font-mono font-bold text-white tracking-tighter">{parsedNumbers.length}</p>
                            </div>
                        </div>
                    </div>

                    {errorMsg && <div className="text-center text-accent-rose font-bold text-xs uppercase tracking-widest py-3 bg-accent-rose/5 rounded-xl border border-accent-rose/10">{errorMsg}</div>}

                    <button onClick={handleCommitBet} disabled={isSubmitting || !totalStake} className="btn-primary w-full h-16 text-sm">
                        {isSubmitting ? 'Authenticating Protocol...' : 'Commit Transaction'}
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

