  z-index: -1;
  background: radial-gradient(circle at 50% 50%, #0f172a 0%, #020617 100%);
  background-size: 200% 200%;
  animation: mesh-flow 15s ease infinite alternate;
}

.animated-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.08) 0%, transparent 50%, rgba(6, 182, 211, 0.08) 100%);
}

/* Professional Glass Panels */
.glass {
  background: rgba(15, 23, 42, 0.65);
  backdrop-filter: blur(32px);
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.7);
}

/* Refined Circular Card - Coin/Node Style */
.circular-game-card {
  @apply aspect-square rounded-full flex flex-col items-center justify-center transition-all duration-700 hover:shadow-[0_0_60px_rgba(99,102,241,0.3)] hover:-translate-y-3 active:scale-95 relative overflow-hidden;
  background: linear-gradient(145deg, rgba(30, 41, 59, 0.5), rgba(15, 23, 42, 0.95));
  border: 1px solid rgba(255, 255, 255, 0.05);
}

/* High-Impact Inputs */
input, select, textarea {
  @apply bg-slate-900/80 border border-slate-800 rounded-2xl px-6 py-5 text-sm transition-all focus:border-accent-indigo focus:ring-8 focus:ring-accent-indigo/10 focus:outline-none text-slate-100 placeholder:text-slate-600 shadow-inner font-medium w-full;
}

/* Tactical Buttons */
.btn-primary {
  @apply bg-accent-indigo hover:bg-indigo-500 text-white font-bold py-5 px-12 rounded-full transition-all shadow-2xl shadow-indigo-500/20 active:scale-95 disabled:opacity-50 relative overflow-hidden uppercase tracking-[0.2em] text-xs sm:text-sm;
}

.btn-primary::before {
  content: '';
  @apply absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent;
  transform: translateX(-100%);
  animation: shimmer 2s infinite;
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

.card {
  @apply glass rounded-[3rem] p-10 sm:p-16;
}

/* Utility: Custom Scrollbars */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { @apply bg-slate-800/50 rounded-full hover:bg-slate-700 transition-colors; }

.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

.winning-ball-reveal {
  @apply w-40 h-40 sm:w-64 sm:h-64 rounded-full flex items-center justify-center bg-white text-black font-black text-6xl sm:text-9xl shadow-[0_0_80px_rgba(255,255,255,0.4)] border-8 border-accent-indigo;
}

